∀ {X : Type u} {p₁ p₂ : X → Prop} [inst : TopologicalSpace.{u} X],
  @IsClosed.{u} X inst (@Set.ofPred.{u} X fun x => p₁ x) →
    @IsClosed.{u} X inst (@Set.ofPred.{u} X fun x => p₂ x) →
      @IsClosed.{u} X inst (@Set.ofPred.{u} X fun x => And (p₁ x) (p₂ x))

∀ {X : Type u} [inst : TopologicalSpace.{u} X] {ι : Type u_2} {s : ι → Set.{u} X},
  (∀ (i : ι), @IsClosed.{u} X inst (s i)) →
    @Set.Finite.{u_2} ι (@Set.ofPred.{u_2} ι fun i => @Set.Nonempty.{u} X (s i)) → @IsClosed.{u} X inst (⋃ i, s i)

∀ {X : Type u} {s₁ s₂ : Set.{u} X} [inst : TopologicalSpace.{u} X],
  @IsClosed.{u} X inst s₁ →
    @IsClosed.{u} X inst s₂ → @IsClosed.{u} X inst (@Inter.inter.{u} (Set.{u} X) (@Set.instInter.{u} X) s₁ s₂)

∀ {X : Type u} {s t : Set.{u} X} [inst : TopologicalSpace.{u} X],
  @IsClosed.{u} X inst s →
    @IsOpen.{u} X inst t → @IsClosed.{u} X inst (@SDiff.sdiff.{u} (Set.{u} X) (@Set.instSDiff.{u} X) s t)

∀ {X : Type u} {s₁ s₂ : Set.{u} X} [inst : TopologicalSpace.{u} X],
  @IsClosed.{u} X inst s₁ →
    @IsClosed.{u} X inst s₂ → @IsClosed.{u} X inst (@Union.union.{u} (Set.{u} X) (@Set.instUnion.{u} X) s₁ s₂)

∀ {X : Type u} {p₁ p₂ : X → Prop} [inst : TopologicalSpace.{u} X],
  @IsOpen.{u} X inst (@Set.ofPred.{u} X fun x => p₁ x) →
    @IsOpen.{u} X inst (@Set.ofPred.{u} X fun x => p₂ x) →
      @IsOpen.{u} X inst (@Set.ofPred.{u} X fun x => And (p₁ x) (p₂ x))

∀ {X : Type u} [inst : TopologicalSpace.{u} X] {ι : Type u_2} {s : ι → Set.{u} X},
  (∀ (i : ι), @IsOpen.{u} X inst (s i)) →
    @Set.Finite.{u_2} ι (@Set.ofPred.{u_2} ι fun i => @Ne.{u + 1} (Set.{u} X) (s i) (@Set.univ.{u} X)) →
      @IsOpen.{u} X inst (⋂ i, s i)

∀ {X : Type u} {s t : Set.{u} X} [inst : TopologicalSpace.{u} X],
  @IsOpen.{u} X inst s →
    @IsClosed.{u} X inst t → @IsOpen.{u} X inst (@SDiff.sdiff.{u} (Set.{u} X) (@Set.instSDiff.{u} X) s t)

∀ {X : Type u} {s₁ s₂ : Set.{u} X} [inst : TopologicalSpace.{u} X],
  @IsOpen.{u} X inst s₁ →
    @IsOpen.{u} X inst s₂ → @IsOpen.{u} X inst (@Union.union.{u} (Set.{u} X) (@Set.instUnion.{u} X) s₁ s₂)

∀ {X : Type u} {α : Type u_1} [inst : TopologicalSpace.{u} X] {s : Set.{u_1} α} {f : α → Set.{u} X},
  @Set.Finite.{u_1} α s →
    (∀ (i : α),
        @Membership.mem.{u_1, u_1} α (Set.{u_1} α) (@Set.instMembership.{u_1} α) s i → @IsClosed.{u} X inst (f i)) →
      @IsClosed.{u} X inst
        (⋃ i, ⋃ (_ : @Membership.mem.{u_1, u_1} α (Set.{u_1} α) (@Set.instMembership.{u_1} α) s i), f i)

∀ {X : Type u} [inst : TopologicalSpace.{u} X] {s : Set.{u} (Set.{u} X)},
  @Set.Finite.{u} (Set.{u} X) s →
    (∀ (t : Set.{u} X),
        @Membership.mem.{u, u} (Set.{u} X) (Set.{u} (Set.{u} X)) (@Set.instMembership.{u} (Set.{u} X)) s t →
          @IsClosed.{u} X inst t) →
      @IsClosed.{u} X inst (@Set.sUnion.{u} X s)

∀ {X : Type u} {α : Type u_1} [inst : TopologicalSpace.{u} X] {s : Set.{u_1} α} {f : α → Set.{u} X},
  @Set.Finite.{u_1} α s →
    (∀ (i : α),
        @Membership.mem.{u_1, u_1} α (Set.{u_1} α) (@Set.instMembership.{u_1} α) s i → @IsOpen.{u} X inst (f i)) →
      @IsOpen.{u} X inst
        (⋂ i, ⋂ (_ : @Membership.mem.{u_1, u_1} α (Set.{u_1} α) (@Set.instMembership.{u_1} α) s i), f i)

∀ {X : Type u} [inst : TopologicalSpace.{u} X] {s : Set.{u} (Set.{u} X)},
  @Set.Finite.{u} (Set.{u} X) s →
    (∀ (t : Set.{u} X),
        @Membership.mem.{u, u} (Set.{u} X) (Set.{u} (Set.{u} X)) (@Set.instMembership.{u} (Set.{u} X)) s t →
          @IsOpen.{u} X inst t) →
      @IsOpen.{u} X inst (@Set.sInter.{u} X s)

∀ {X : Type u_2} {t₁ t₂ : TopologicalSpace.{u_2} X},
  (∀ (s : Set.{u_2} X), Iff (@IsClosed.{u_2} X t₁ s) (@IsClosed.{u_2} X t₂ s)) →
    @Eq.{u_2 + 1} (TopologicalSpace.{u_2} X) t₁ t₂

{X : Type u} →
  (T : Set.{u} (Set.{u} X)) →
    @Membership.mem.{u, u} (Set.{u} X) (Set.{u} (Set.{u} X)) (@Set.instMembership.{u} (Set.{u} X)) T
        (@EmptyCollection.emptyCollection.{u} (Set.{u} X) (@Set.instEmptyCollection.{u} X)) →
      (∀ (A : Set.{u} (Set.{u} X)),
          @LE.le.{u} (Set.{u} (Set.{u} X)) (@Set.instLE.{u} (Set.{u} X)) A T →
            @Membership.mem.{u, u} (Set.{u} X) (Set.{u} (Set.{u} X)) (@Set.instMembership.{u} (Set.{u} X)) T
              (@Set.sInter.{u} X A)) →
        (∀ (A : Set.{u} X),
            @Membership.mem.{u, u} (Set.{u} X) (Set.{u} (Set.{u} X)) (@Set.instMembership.{u} (Set.{u} X)) T A →
              ∀ (B : Set.{u} X),
                @Membership.mem.{u, u} (Set.{u} X) (Set.{u} (Set.{u} X)) (@Set.instMembership.{u} (Set.{u} X)) T B →
                  @Membership.mem.{u, u} (Set.{u} X) (Set.{u} (Set.{u} X)) (@Set.instMembership.{u} (Set.{u} X)) T
                    (@Union.union.{u} (Set.{u} X) (@Set.instUnion.{u} X) A B)) →
          TopologicalSpace.{u} X

∀ {X : Type u} {α : Type u_1} [inst : TopologicalSpace.{u} X] {s : Set.{u_1} α} {f : α → Set.{u} X},
  (∀ (i : α),
      @Membership.mem.{u_1, u_1} α (Set.{u_1} α) (@Set.instMembership.{u_1} α) s i → @IsClosed.{u} X inst (f i)) →
    @IsClosed.{u} X inst
      (⋂ i, ⋂ (_ : @Membership.mem.{u_1, u_1} α (Set.{u_1} α) (@Set.instMembership.{u_1} α) s i), f i)

∀ {X : Type u} {α : Type u_1} [inst : TopologicalSpace.{u} X] {s : Finset.{u_1} α} {f : α → Set.{u} X},
  (∀ (i : α),
      @Membership.mem.{u_1, u_1} α (Finset.{u_1} α)
          (@SetLike.instMembership.{u_1, u_1} (Finset.{u_1} α) α (@Finset.instSetLike.{u_1} α)) s i →
        @IsClosed.{u} X inst (f i)) →
    @IsClosed.{u} X inst
      (⋃ i,
        ⋃ (_ :
          @Membership.mem.{u_1, u_1} α (Finset.{u_1} α)
            (@SetLike.instMembership.{u_1, u_1} (Finset.{u_1} α) α (@Finset.instSetLike.{u_1} α)) s i),
          f i)

∀ {X : Type u} [inst : TopologicalSpace.{u} X] {p q : X → Prop},
  @IsOpen.{u} X inst (@Set.ofPred.{u} X fun x => p x) →
    @IsClosed.{u} X inst (@Set.ofPred.{u} X fun x => q x) → @IsClosed.{u} X inst (@Set.ofPred.{u} X fun x => p x → q x)

∀ {X : Type u} [inst : TopologicalSpace.{u} X] {s : Set.{u} (Set.{u} X)},
  (∀ (t : Set.{u} X),
      @Membership.mem.{u, u} (Set.{u} X) (Set.{u} (Set.{u} X)) (@Set.instMembership.{u} (Set.{u} X)) s t →
        @IsClosed.{u} X inst t) →
    @IsClosed.{u} X inst (@Set.sInter.{u} X s)

∀ {X : Type u} {α : Type u_1} [inst : TopologicalSpace.{u} X] {s : Finset.{u_1} α} {f : α → Set.{u} X},
  (∀ (i : α),
      @Membership.mem.{u_1, u_1} α (Finset.{u_1} α)
          (@SetLike.instMembership.{u_1, u_1} (Finset.{u_1} α) α (@Finset.instSetLike.{u_1} α)) s i →
        @IsOpen.{u} X inst (f i)) →
    @IsOpen.{u} X inst
      (⋂ i,
        ⋂ (_ :
          @Membership.mem.{u_1, u_1} α (Finset.{u_1} α)
            (@SetLike.instMembership.{u_1, u_1} (Finset.{u_1} α) α (@Finset.instSetLike.{u_1} α)) s i),
          f i)

∀ {X : Type u} {α : Type u_1} [inst : TopologicalSpace.{u} X] {s : Set.{u_1} α} {f : α → Set.{u} X},
  (∀ (i : α), @Membership.mem.{u_1, u_1} α (Set.{u_1} α) (@Set.instMembership.{u_1} α) s i → @IsOpen.{u} X inst (f i)) →
    @IsOpen.{u} X inst (⋃ i, ⋃ (_ : @Membership.mem.{u_1, u_1} α (Set.{u_1} α) (@Set.instMembership.{u_1} α) s i), f i)

∀ {X : Type u} {s : Set.{u} X} {p : Set.{u} X → Prop} {h₁ : p (@Set.univ.{u} X)}
  {h₂ : ∀ (s t : Set.{u} X), p s → p t → p (@Inter.inter.{u} (Set.{u} X) (@Set.instInter.{u} X) s t)}
  {h₃ :
    ∀ (s : Set.{u} (Set.{u} X)),
      (∀ (t : Set.{u} X),
          @Membership.mem.{u, u} (Set.{u} X) (Set.{u} (Set.{u} X)) (@Set.instMembership.{u} (Set.{u} X)) s t → p t) →
        p (@Set.sUnion.{u} X s)},
  Iff (@IsOpen.{u} X (@TopologicalSpace.mk.{u} X p h₁ h₂ h₃) s) (p s)

∀ {X : Type u} [inst : TopologicalSpace.{u} X] {f : Filter.{u} X}
  (h :
    ∃ x,
      @LE.le.{u} (Filter.{u} X)
        (@Preorder.toLE.{u} (Filter.{u} X)
          (@PartialOrder.toPreorder.{u} (Filter.{u} X) (@Filter.instPartialOrder.{u} X)))
        f (@nhds.{u} X inst x)),
  @LE.le.{u} (Filter.{u} X)
    (@Preorder.toLE.{u} (Filter.{u} X) (@PartialOrder.toPreorder.{u} (Filter.{u} X) (@Filter.instPartialOrder.{u} X))) f
    (@nhds.{u} X inst (@Filter.lim.{u} X inst ⋯ f))

∀ {X : Type u} {α : Type u_1} [inst : TopologicalSpace.{u} X] [hX : Nonempty.{u + 1} X] {f : Filter.{u_1} α}
  {g : α → X},
  Not (∃ x, @Filter.Tendsto.{u_1, u} α X g f (@nhds.{u} X inst x)) →
    @Eq.{u + 1} X (@Filter.limUnder.{u, u_1} X inst α hX f g) (@Classical.choice.{u + 1} X hX)

∀ {X : Type u} {α : Type u_1} [inst : TopologicalSpace.{u} X] {f : Filter.{u_1} α} {g : α → X}
  (h : ∃ x, @Filter.Tendsto.{u_1, u} α X g f (@nhds.{u} X inst x)),
  @Filter.Tendsto.{u_1, u} α X g f (@nhds.{u} X inst (@Filter.limUnder.{u, u_1} X inst α ⋯ f g))
